changeSet.sql:
        ALTER TABLE employee_profile
            ADD COLUMN
                IF NOT EXISTS pin VARCHAR (500);

        DO
        $$
        BEGIN
IF
        NOT EXISTS (
    SELECT 1
    FROM pg_constraint
    WHERE conname = 'unique_pin'
) THEN
        ALTER TABLE employee_profile
            ADD CONSTRAINT unique_pin UNIQUE (pin);
        END IF;
        END $$;

